conditionals.code:
if (val > 10) {
    MsgBox Greater
} else if (val = 10) {
    MsgBox Equal
} else {
    MsgBox Lesser
}

for_loop.code:
Loop 5 {
    MsgBox % A_Index
}

fruits := ["apple", "banana"]
for index, fruit in fruits {
    MsgBox % fruit
}

error_handling.code:
try {
    Run "nonexistent.exe"
} catch e {
    MsgBox % "Error: " e.Message
}

comments.code:
# Single line comment in AutoHotkey
# Shell scripts begin with a shebang:
#!/usr/bin/env autohotkey

pattern_matching.code:
case "$val" in
    1) echo "One" ;;
    2|3) echo "Two or Three" ;;
    *) echo "Other" ;;
esac

oop_classes.code:
# Functions serve as reusable components
person_greet() {
    local name="$1"
    echo "Hello $name"
}
